import{_ as o,C as t,o as r,c as h,a4 as e,E as s}from"./chunks/framework.BNWYI55R.js";const F=JSON.parse('{"title":"AI使用指南：连接验证、节点配置与访问问题排查","description":"AI与网络故障标准化排查指南。涵盖资格核对、客户端订阅导入、首连验证、登录403/429排查、长对话断流修复、终端API环境配置与DNS防污染。","frontmatter":{"title":"AI使用指南：连接验证、节点配置与访问问题排查","description":"AI与网络故障标准化排查指南。涵盖资格核对、客户端订阅导入、首连验证、登录403/429排查、长对话断流修复、终端API环境配置与DNS防污染。","h1":"AI使用指南：连接验证、节点配置与访问问题排查","pageType":"hub","canonicalPath":"/guides/","primaryIntent":"操作与排障指南：遇到连接、登录与断流问题时，如何不盲目换机场，依据证据精准定位","verifiedAt":"2026-10-21T00:00:00.000Z","modifiedAt":"2026-10-21T00:00:00.000Z","provenance":"self_measured"},"headers":[],"relativePath":"guides/index.md","filePath":"guides/index.md","lastUpdated":1792566416000}'),d={name:"guides/index.md"};function p(c,a,k,g,u,y){const i=t("DecisionTree"),l=t("FAQBlock"),n=t("RelatedLinks");return r(),h("div",null,[a[0]||(a[0]=e("",8)),s(i),a[1]||(a[1]=e("",125)),s(l,{items:[{q:"为什么我一开启代理软件，国内的微信和百度都打不开了？",a:"<p>这通常是因为你的客户端模式误设为了<strong>Global（全局代理）</strong>，导致所有国内流量被强行绕道海外，而国内网站对境外 IP 有严格的防火墙防护；或者是因为代理客户端在系统设置中强行篡改了全局系统代理，而在客户端异常崩溃退出后没有自动还原网络设置。解决办法是将模式切回<strong>Rule（规则分流）</strong>；若依然断网，进入系统设置-网络-代理，手动关闭“使用代理服务器”开关即可恢复。</p>"},{q:"在浏览器中使用 ChatGPT 提示“检测到代理”，该怎么处理？",a:"<p>这说明当前节点出口的 IP 声誉评分已落入高危区间。标准化应对三步法：① 在客户端中手动切换至另一个标注为“专线”或“原生”的日本/新加坡节点；② 打开 Chrome 无痕隐身窗口；③ 检查客户端是否关闭了 WebRTC 泄露防护。绝大多数情况下，更换清洁节点并清理缓存后即可立刻恢复正常。</p>"},{q:"代码中调用 OpenAI API 频繁报 504 Gateway Timeout 是怎么回事？",a:"<p>504 超时通常意味着代理服务器在向 OpenAI 网关发起握手时，长时间未收到任何响应。这通常由两大因素引起：① OpenAI 后端服务器正在遭受高峰期流量拥堵或临时维护；② 机场节点的底层国际专线发生光缆抖动。建议在代码中引入指数退避重试（Exponential Backoff Retry）机制，并在客户端中切换备用节点测试。</p>"},{q:"为什么我的客户端节点延迟显示是绿色的 30ms，但实际上网依然卡顿？",a:"<p>在客户端面板上看到的绿色 30ms，通常只是从你本地电脑到机场国内入口中转机房（如深圳、上海）的 TCP 握手延迟（Ping 值），它<strong>完全不能代表海外落地机房到目标网站（如 OpenAI）的真实通信速度</strong>。如果机场的跨境内网专线严重超售、或者海外出口机房带宽打满，即便本地 Ping 是绿色的，实际访问依然会像蜗牛一样慢。必须以真实的网页打开速度与视频加载吞吐为准。</p>"},{q:"开启代理客户端后，为什么家庭局域网内的群晖 NAS、私有云或无线打印机搜不到了？",a:"<p>这是因为代理客户端开启了全局接管或 TUN 虚拟网卡模式，将原本属于本地局域网（192.168.x.x / 10.x.x.x / 172.16.x.x）的广播流量也错误地导向了海外代理通道，导致局域网设备发现协议（mDNS / SSDP）失效。解决对策：进入代理客户端设置，勾选<strong>“绕过局域网（Bypass LAN）”</strong>与<strong>“允许局域网直接连接”</strong>选项，或者在分流规则的最顶部添加一条 <code>IP-CIDR,192.168.0.0/16,DIRECT</code> 强制直连规则。</p>"},{q:"如何快速判断是机场节点故障，还是目标网站服务自身宕机？",a:"<p>最科学的二分法测试：① 打开浏览器访问 <code>https://www.google.com</code> 或 <code>https://www.cloudflare.com</code>。如果 Google 和 Cloudflare 能够秒开，说明你的机场代理隧道完全正常；此时如果唯独打不开 ChatGPT，则必然是 OpenAI 服务端临时维护或该出口 IP 触发了局部风控；② 反之，如果连 Google 都完全打不开，且多个节点均无法握手，则说明是机场国内入口故障或本地网络中断。</p>"}]}),s(n,{links:[{title:"AI机场专项选型指南 (/ai/)",desc:"深入查看哪些机场在 ChatGPT 与 Claude 上拥有详实抓包记录",url:"/ai/"},{title:"解锁实测中心 (/tests/)",desc:"查阅最新测试批次的各地区抓包数据与真实时延",url:"/tests/"},{title:"综合机场推荐榜 (/recommend/)",desc:"综合对比主力专线与备用容灾方案",url:"/recommend/"},{title:"节点地区深度指南 (/regions/)",desc:"了解官方支持国家政策与物理海缆路由分布",url:"/regions/"}]})])}const P=o(d,[["render",p]]);export{F as __pageData,P as default};
